package studio.jiayu.neoagent;
import android.app.Activity;import android.os.*;import android.widget.*;import android.view.accessibility.AccessibilityNodeInfo;import org.json.*;import java.io.*;
/** Native node identity survives transient agent numbering; no financial gesture is sent. */
final class RejectionContracts {
 static void yes(boolean b,String m)throws Exception{if(!b)throw new Exception(m);}
 static void start(Activity a){LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(40,140,40,40);Button dangerous=new Button(a);dangerous.setText("立即支付");box.addView(dangerous);Button safe=new Button(a);safe.setText("其他入口");box.addView(safe);a.setContentView(box);new Handler().postDelayed(()->run(a),800);}
 static void run(Activity a){JSONObject result=new JSONObject();int count=0;ControlService s=ControlService.instance;try{yes(s!=null&&s.connected&&!s.busy(),"Runtime not idle");AccessibilityNodeInfo root=s.getRootInActiveWindow();yes(root!=null&&a.getPackageName().contentEquals(root.getPackageName()),"Owned fixture not foreground");count++;AccessibilityNodeInfo node=null;for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText("立即支付"))if("立即支付".contentEquals(n.getText()))node=n;yes(node!=null,"Owned financial node missing");count++;ControlService.Observation first=new ControlService.Observation();first.signature=GuiRevision.signature(root);first.identities.put(7,GuiRevision.identity(node));Action action=Action.parse("{\"action\":\"tap\",\"id\":7}");s.rejectedActions.clear();s.requireNewCandidate(first,action);boolean blocked=false;try{s.checkTarget(node);}catch(ControlService.LocalBoundaryException denied){blocked=true;s.recordRejected(first,action,denied.getMessage());}yes(blocked,"Financial candidate was not rejected");count++;
 ControlService.Observation renumbered=new ControlService.Observation();renumbered.signature=first.signature;renumbered.identities.put(91,GuiRevision.identity(node));Action retry=Action.parse("{\"action\":\"tap\",\"id\":91}");blocked=false;try{s.requireNewCandidate(renumbered,retry);}catch(ControlService.LocalBoundaryException denied){blocked=true;}yes(blocked,"New transient ID bypassed rejected candidate feedback");count++;JSONArray feedback=s.rejectionFeedback(renumbered);yes(feedback.length()==1&&feedback.getJSONObject(0).getInt("id")==91&&!feedback.getJSONObject(0).getBoolean("executed"),"Feedback did not resolve current native ID");count++;
 s.requireNewCandidate(renumbered,Action.parse("{\"action\":\"purchase_check\"}"));count++;s.requireNewCandidate(renumbered,Action.parse("{\"action\":\"back\"}"));count++;result.put("success",true);
 }catch(Exception e){try{result.put("success",false).put("failure",e.getMessage());}catch(Exception ignored){}}finally{if(s!=null)s.rejectedActions.clear();try(FileOutputStream out=a.openFileOutput("rejection-contracts.json",0)){out.write(result.put("passed",count).put("real_network_calls",0).put("third_party_actions",0).put("financial_gestures",0).toString(2).getBytes("UTF-8"));}catch(Exception ignored){}a.finish();}}
}
